        largest = i
        l = 2 * i + 1
        r = 2 * i + 2

        if l < n and arr[l] > arr[largest]:
            largest = l

        if r < n and arr[r] > arr[largest]:
            largest = r

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify_and_pop(arr, n, largest, k)

    n = len(nums)
    for i in range(n // 2 - 1, -1, -1):
        heapify_and_pop(nums, n, i, k)

    for _ in range(k - 1):
        nums[0], nums[n - 1] = nums[n - 1], nums[0]
        n -= 1
        heapify_and_pop(nums, n, 0, k)

    return nums[0]
