import random

def quickselect(nums, k):
    if not nums:
        return None

    low = 0
    high = len(nums) - 1

    while low <= high:
        pivot_index = random.randint(low, high)
        pivot = nums[pivot_index]

        i = low
        j = high

        while i <= j:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1

            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1

        if k <= j + 1:
            high = j
        elif k > i:
            low = i
        else:
            return pivot

    return nums[k-1]

def solve(nums, k):
    return quickselect(nums.copy(), k)
