def quickselect(arr, k):
    if not arr:
        return None

    def partition(l, r):
        pivot = arr[r]
        i = l
        for j in range(l, r):
            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[r] = arr[r], arr[i]
        return i

    l, r = 0, len(arr) - 1
    while l <= r:
        p = partition(l, r)
        if p == k - 1:
            return arr[p]
        elif p < k - 1:
            l = p + 1
        else:
