def solve(nums, k):
    """
    Finds the k-th smallest value in nums using quickselect.

    Args:
        nums: A list of integers.
        k: An integer representing the desired k-th smallest value (1-indexed).

    Returns:
        The k-th smallest value in nums.
    """

    def partition(l, r, pivot_index):
        pivot = nums[pivot_index]
        nums[pivot_index], nums[r] = nums[r], nums[pivot_index]
        i = l
        for j in range(l, r):
            if nums[j] <= pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[r] = nums[r], nums[i]
        return i

    def quickselect(l, r, k):
        if l == r:
            return nums[l]

        pivot_index = (l + r) // 2
        pivot_index = partition(l, r, pivot_index)

        if k == pivot_index + 1:
            return nums[pivot_index]
        elif k < pivot_index + 1:
            return quickselect(l, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, r, k)

    return quickselect(0, len(nums) - 1, k)
