def solve(nums, k):
    def median(arr):
        arr.sort()
        n = len(arr)
        if n % 2 == 0:
            return (arr[n // 2 - 1] + arr[n // 2]) // 2
        else:
            return arr[n // 2]

    def quickselect(arr, left, right, k):
        if left == right:
            return arr[left]

        pivot_index = (left + right) // 2
        pivot = arr[pivot_index]

        i = left
        j = right

        while i <= j:
            while arr[i] < pivot:
                i += 1
            while arr[j] > pivot:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1

        quickselect(arr, left, j, k)
        quickselect(arr, i, right, k)

    n = len(nums)
    if n == 1:
        return nums[0]

    if k == 1:
        return min(nums)

    if k == n:
        return max(nums)

    medians = []
    for i in range(0, n, len(nums) // 5):
        medians.append(median(nums[i:i + len(nums) // 5]))

    median_of_medians = median(medians)

    left = 0
    right = n - 1

    while left <= right:
        pivot_index = (left + right) // 2
        pivot = nums[pivot_index]

        less = 0
        equal = 0
        greater = 0

        for num in nums:
            if num < pivot:
                less += 1
            elif num == pivot:
                equal += 1
            else:
                greater += 1

        if less < k - 1 and less + equal >= k:
            return pivot
        elif less >= k:
            right = pivot_index - 1
        else:
            left = pivot_index + 1

    return -1
