def solve(nums, k):
    def median(arr):
        arr = sorted(arr)
        n = len(arr)
        if n % 2 == 0:
            return (arr[n // 2 - 1] + arr[n // 2]) / 2
        else:
            return arr[n // 2]

    def partition(arr, left, right, pivot):
        i = left
        j = right
        while i <= j:
            while arr[i] < pivot:
                i += 1
            while arr[j] > pivot:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1
        return i

    def quickselect(arr, left, right, k):
        if left == right:
            return arr[left]

        pivot = arr[partition(arr, left, right, arr[right])]
        if k == pivot:
            return pivot
        elif k < pivot:
            return quickselect(arr, left, pivot - 1, k)
        else:
            return quickselect(arr, pivot + 1, right, k)

    return quickselect(nums, 0, len(nums) - 1, k)
