        return None

    min_val = min(nums)
    max_val = max(nums)
    range_val = max_val - min_val + 1

    count = [0] * range_val

    for num in nums:
        count[num - min_val] += 1

    for i in range(range_val):
        if count[i] >= k:
            return i + min_val
