def solve(n, edges, s, t):
    if s == t:
        return 0

    dist = [float('inf')] * n
    dist[s] = 0

    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v]:
            return -1

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
