def solve(nums):
    """
    Finds the repeated value in a list of integers where one value occurs more than once.
    """
    low = 1
    high = len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        count = 0
        for num in nums:
            if num == mid:
                count += 1
        if count > 1:
            return mid
        elif nums[mid] < mid + 1:
            low = mid + 1
        else:
            high = mid - 1
    return -1
