import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    dist = {(r, c): float('inf') for r in range(rows) for c in range(cols)}
    dist[start] = 0
    pq = [(0, start)]
    prev = {}

    while pq:
        d, curr = heapq.heappop(pq)

        if d > dist[curr]:
            continue

        if curr == goal:
            path = []
            while curr in prev:
                path.append(curr)
                curr = prev[curr]
            path.append(start)
            return path[::-1]

        r, c = curr
        neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

        for nr, nc in neighbors:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and dist[(nr, nc)] > d + 1:
                dist[(nr, nc)] = d + 1
                prev[(nr, nc)] = curr
                heapq.heappush(pq, (d + 1, (nr, nc)))

    return []
```

