        if index == len(intervals):
            return 0

        # Option 1: Skip the current interval
        skip = helper(index + 1)

        # Option 2: Take the current interval
        take = 1 + helper(index + 1)

        # Check for overlap with previously taken intervals
        overlap = False
        for i in range(index):
            if intervals[i][1] > intervals[index][0]:
                overlap = True
                break

        if not overlap:
            take = 1 + helper(index + 1)

        return min(skip, take)

