def solve(intervals):
    if not intervals:
        return []

    parent = list(range(len(intervals)))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if max(intervals[i][0], intervals[j][0]) <= min(intervals[i][1], intervals[j][1]):
                union(i, j)

    merged = []
    representative = {}
    for i in range(len(intervals)):
        root = find(i)
        if root not in representative:
            representative[root] = intervals[i]
            merged.append(intervals[i])

    merged.sort(key=lambda x: x[0])
    result = []
    if not merged:
        return []
    result.append(merged[0])
    for i in range(1, len(merged)):
        if merged[i][0] >= result[-1][1]:
            result.append(merged[i])
        else:
            result[-1][1] = max(result[-1][1], merged[i][1])
    return result
