import heapq

def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    heap = []
    for num, count in counts.items():
        heapq.heappush(heap, (count, num))
        if len(heap) > k:
            heapq.heappop(heap)

    result = []
    while heap:
        count, num = heapq.heappop(heap)
        result.append(num)

    return result
