def solve(nums):
    if not nums:
        return 0

    compressed_nums = []
    for num in nums:
        if not compressed_nums or num > compressed_nums[-1]:
            compressed_nums.append(num)
        else:
            l, r = 0, len(compressed_nums) - 1
            while l <= r:
                mid = (l + r) // 2
                if compressed_nums[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            compressed_nums[l] = num

    n = len(compressed_nums)
    if n == 0:
        return 0

    bit = [0] * (n + 1)

    def update(i, val):
        i += 1
        while i <= n:
            bit[i] = max(bit[i], val)
            i += i & -i

    def query(i):
        i += 1
        res = 0
        while i > 0:
            res = max(res, bit[i])
            i -= i & -i
        return res

    for i in range(n):
        length = query(i) + 1
        update(i, length)

    return query(n - 1)
```

