from collections import deque

def solve(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    parent = [-1] * n

    for start_node in range(n):
        if not visited[start_node]:
            queue = deque([start_node])
            visited[start_node] = True

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
                        parent[v] = u
                    elif v != parent[u]:
                        return True

    return False
```

